CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'CUSTOMER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL,image TEXT,file_path TEXT,active INTEGER DEFAULT 1,featured INTEGER DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id TEXT PRIMARY KEY,user_id TEXT,type TEXT NOT NULL,total_amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,product_id TEXT NOT NULL,quantity INTEGER NOT NULL,unit_price INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE payments (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,gateway TEXT NOT NULL,transaction_id TEXT UNIQUE,amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',expires_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE download_tokens (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,product_id TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMP NOT NULL,used_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,technologies TEXT,year INTEGER,status TEXT,demo_url TEXT,source_url TEXT,featured INTEGER DEFAULT 0);
CREATE TABLE testimonials (id TEXT PRIMARY KEY,author TEXT NOT NULL,body TEXT NOT NULL,active INTEGER DEFAULT 1);
